"use server";

import { apiv3Get } from "@/lib/apiv3";

/**
 * Server action — supplier (operatör) dizini, apiv3 suppliers.
 * apiv3 b2c uçları `X-App-Token` (server-side gizli) ister; bu yüzden client
 * component'ler bu action'ı RPC ile çağırır. apiv3 { data: [...] } döner; çağıranlar
 * düz dizi beklediği için unwrap edilir.
 */
type SupplierListParams = {
  limit?: number;
  withtours?: boolean;
  withimage?: boolean;
  order?: "tourcount";
};

export async function getSuppliers(params: SupplierListParams = {}) {
  const query = new URLSearchParams();
  if (params.limit) query.set("limit", String(params.limit));
  if (params.withtours) query.set("withtours", "true");
  if (params.withimage) query.set("withimage", "true");
  if (params.order) query.set("order", params.order);

  const qs = query.toString();
  const res = await apiv3Get(`/suppliers${qs ? `?${qs}` : ""}`, { cache: "force-cache" });

  if (!res.ok) throw new Error("Failed to fetch data");

  const json = await res.json();
  return json.data ?? [];
}
